function boxBlur(data,w,h,radius){
  var r=Math.max(0,Math.round(radius));
  if(r===0) return data;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sr=0,sg=0,sb=0,sa=0,n=0;
    for(var yy=Math.max(0,y-r);yy<=Math.min(h-1,y+r);yy++) for(var xx=Math.max(0,x-r);xx<=Math.min(w-1,x+r);xx++){
      var i=(yy*w+xx)*4; sr+=data[i]; sg+=data[i+1]; sb+=data[i+2]; sa+=data[i+3]; n++;
    }
    var p=(y*w+x)*4; out[p]=sr/n; out[p+1]=sg/n; out[p+2]=sb/n; out[p+3]=sa/n;
  }
  return out;
}
function tiltShiftProcess(data,w,h,opts){
  opts=opts||{};
  var blur=opts.blur!=null?opts.blur:6;
  var band=opts.band!=null?opts.band:0.25;
  var pos=opts.position!=null?opts.position:0.5;
  if(blur<0)blur=0; else if(blur>20)blur=20;
  if(band<0.05)band=0.05; else if(band>0.6)band=0.6;
  if(pos<0)pos=0; else if(pos>1)pos=1;
  var soft=band*0.8+0.05;
  var blurred=boxBlur(data,w,h,blur);
  var out=new Uint8ClampedArray(data.length);
  var fy=pos*h;
  for(var y=0;y<h;y++){
    var dist=Math.abs(y-fy)/h;
    var k;
    if(dist<=band) k=0;
    else if(dist>=band+soft) k=1;
    else k=(dist-band)/soft;
    for(var x=0;x<w;x++){
      var p=(y*w+x)*4;
      out[p]=data[p]*(1-k)+blurred[p]*k;
      out[p+1]=data[p+1]*(1-k)+blurred[p+1]*k;
      out[p+2]=data[p+2]*(1-k)+blurred[p+2]*k;
      out[p+3]=data[p+3];
    }
  }
  return out;
}

var EXPORTS={tiltShiftProcess:tiltShiftProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TiltShiftForgePure = EXPORTS; }
